          },
          "value": {
            "type": "string"
          }
        }
      },
      {
        "id": "ComposeDictionaries",
        "type": "object",
        "additionalProperties": {
          "type": "boolean"
        },
        "description": "A <em>dictionary object</em> with entries for all installed dictionaries, having a language identifier as <em>key</em> (for example <value>en-US</value>) and a boolean expression as <em>value</em>, indicating whether that dictionary is enabled for spellchecking or not."
      },
      {
        "id": "EncryptionPropertiesOpenPGP",
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "pattern": "^OpenPGP$"
          },
          "encryptBody": {
            "type": "boolean",
            "description": "Whether encryption of the message body using the OpenPGP technology is enabled. **Note:** If encryption is enabled, but the `preconditions <https://support.mozilla.org/en-US/kb/thunderbird-help-cannot-encrypt>`__ for sending an encrypted message are not met, the message cannot be sent."
          },
          "encryptSubject": {
            "type": "boolean",
            "description": "Whether encryption of the message subject using the OpenPGP technology is enabled (only supported if encryption of the body is enabled a well)."
          },
          "signMessage": {
            "type": "boolean",
            "description": "Whether the message will be signed using the OpenPGP technology."
          }
        }
      },
      {
        "id": "EncryptionPropertiesSMIME",
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "pattern": "^S/MIME$"
          },
          "encryptBody": {
            "type": "boolean",
            "description": "Whether encryption of the message body using the S/MIME technology is enabled. **Note:** If encryption is enabled, but the `preconditions <https://support.mozilla.org/en-US/kb/thunderbird-help-cannot-encrypt>`__ for sending an encrypted message are not met, the message cannot be sent."
          },
          "signMessage": {
            "type": "boolean",
            "description": "Whether the message will be signed using the S/MIME technology"
          }
        }
      }
    ],
    "events": [
      {
        "name": "onBeforeSend",
        "type": "function",
        "description": "Fired when a message is about to be sent from the compose window. This is a user input event handler. For asynchronous listeners some `restrictions <|link-user-input-restrictions|>`__ apply.",
        "permissions": ["compose"],
        "parameters": [
          {
            "name": "tab",
            "$ref": "tabs.Tab"
          },
          {
            "name": "details",
            "$ref": "ComposeDetails",
            "description": "The current state of the compose window. This is functionally the same as calling the :ref:`compose.getComposeDetails` function."
          }
        ],
        "returns": {
          "type": "object",
          "properties": {
            "cancel": {
              "type": "boolean",
              "optional": true,
              "description": "Cancels the send."
            },
            "details": {
              "$ref": "ComposeDetails",
              "optional": true,
              "description": "Updates the compose window. This is functionally the same as calling the :ref:`compose.setComposeDetails` function."
            }
          }
        }
      },
      {
        "name": "onAfterSend",
        "type": "function",
        "description": "Fired when sending a message succeeded or failed.",
        "permissions": ["compose"],
        "parameters": [
          {
            "name": "tab",
            "$ref": "tabs.Tab"
          },
          {
            "name": "sendInfo",
            "type": "object",
            "properties": {
              "mode": {
                "type": "string",
                "description": "The used send mode.",
                "enum": ["sendNow", "sendLater"]
              },
              "error": {
                "type": "string",
                "description": "An error description, if sending the message failed.",
                "optional": true
              },
              "headerMessageId": {
                "type": "string",
                "description": "The header messageId of the outgoing message. Only included for actually sent messages.",
                "optional": true
              },
              "messages": {
                "type": "array",
                "items": {
                  "$ref": "messages.MessageHeader"
                },
                "description": "Copies of the sent message. The number of created copies depends on the applied file carbon copy configuration (fcc)."
              }
            }
          }
        ]
      },
      {
        "name": "onAfterSave",
        "type": "function",
        "description": "Fired when saving a message as draft or template succeeded or failed.",
        "permissions": ["compose"],
        "parameters": [
          {
            "name": "tab",
            "$ref": "tabs.Tab"
          },
          {
            "name": "saveInfo",
            "type": "object",
            "properties": {
              "mode": {
                "type": "string",
                "description": "The used save mode.",
                "enum": ["autoSave", "draft", "template"]
              },
              "error": {
                "type": "string",
                "description": "An error description, if saving the message failed.",
                "optional": true
              },
              "messages": {
                "type": "array",
                "items": {
                  "$ref": "messages.MessageHeader"
                },
                "description": "The saved message(s). The number of saved messages depends on the applied file carbon copy configuration (fcc)."
              }
            }
          }
        ]
      },
      {
        "name": "onAttachmentAdded",
        "type": "function",
        "description": "Fired when an attachment is added to a message being composed.",
        "permissions": ["compose"],
        "parameters": [
          {
            "name": "tab",
            "$ref": "tabs.Tab"
          },
          {
            "name": "attachment",
            "$ref": "ComposeAttachment"
          }
        ]
      },
      {
        "name": "onAttachmentRemoved",
        "type": "function",
        "description": "Fired when an attachment is removed from a message being composed.",
        "permissions": ["compose"],
        "parameters": [
          {
            "name": "tab",
            "$ref": "tabs.Tab"
          },
          {
            "name": "attachmentId",
            "type": "integer"
          }
        ]
      },
      {
        "name": "onIdentityChanged",
        "type": "function",
        "description": "Fired when the user changes the identity that will be used to send a message being composed.",
        "permissions": ["accountsRead"],
        "parameters": [
          {
            "name": "tab",
            "$ref": "tabs.Tab"
          },
          {
            "name": "identityId",
            "type": "string"
          }
        ]
      },
      {
        "name": "onComposeStateChanged",
        "type": "function",
        "description": "Fired when the state of the message composer changed.",
        "parameters": [
          {
            "name": "tab",
            "$ref": "tabs.Tab"
          },
          {
            "name": "state",
            "$ref": "ComposeState"
          }
        ]
      },
